# Widget resources are generated on every run, including complete version-6 input ZIPs.
widget_source = 'package uk.co.littledays;\n\nimport android.app.PendingIntent;\nimport android.appwidget.AppWidgetManager;\nimport android.appwidget.AppWidgetProvider;\nimport android.content.ComponentName;\nimport android.content.Context;\nimport android.content.Intent;\nimport android.graphics.*;\nimport android.os.Bundle;\nimport android.util.AtomicFile;\nimport android.widget.RemoteViews;\nimport org.json.*;\nimport java.io.*;\nimport java.nio.charset.StandardCharsets;\nimport java.time.LocalDate;\nimport java.time.temporal.ChronoUnit;\n\npublic class KeepWidget extends AppWidgetProvider {\n @Override public void onUpdate(Context context,AppWidgetManager manager,int[] ids){for(int id:ids)update(context,manager,id);}\n @Override public void onAppWidgetOptionsChanged(Context context,AppWidgetManager manager,int id,Bundle options){update(context,manager,id);}\n @Override public void onReceive(Context context,Intent intent){super.onReceive(context,intent);String a=intent.getAction();if(Intent.ACTION_DATE_CHANGED.equals(a)||Intent.ACTION_TIME_CHANGED.equals(a)||Intent.ACTION_TIMEZONE_CHANGED.equals(a))updateAll(context);}\n public static void updateAll(Context context){try{AppWidgetManager manager=AppWidgetManager.getInstance(context);int[] ids=manager.getAppWidgetIds(new ComponentName(context,KeepWidget.class));for(int id:ids)update(context,manager,id);}catch(RuntimeException e){android.util.Log.w("ADayToKeep","Widget update deferred",e);}}\n static JSONObject read(Context c,String name){try(InputStream in=new AtomicFile(new File(c.getFilesDir(),name)).openRead()){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;while((count=in.read(buffer))!=-1)bytes.write(buffer,0,count);return new JSONObject(bytes.toString("UTF-8"));}catch(Exception e){return new JSONObject();}}\n static void update(Context context,AppWidgetManager manager,int id){try{\n  JSONObject data=read(context,"data.json"),skin=read(context,"widget-skin.json");JSONArray tasks=data.optJSONArray("tasks");LocalDate today=LocalDate.now();int total=0,completed=0;boolean auto=data.optBoolean("resetDaily",true);\n  if(tasks!=null)for(int i=0;i<tasks.length();i++){JSONObject task=tasks.optJSONObject(i);if(task==null)continue;boolean due=true;try{LocalDate anchor=LocalDate.parse(task.optString("createdOn",today.toString()));long days=ChronoUnit.DAYS.between(anchor,today);due=days>=0&&days%Math.max(1,task.optInt("repeat",1))==0;}catch(Exception ignored){}if(!due)continue;total++;boolean done=task.optBoolean("done");if(auto&&!today.toString().equals(task.optString("completedOn")))done=false;if(done)completed++;}\n  int ink=skin.optInt("ink",0xFF75576C),pink=skin.optInt("pink",0xFFF7DCE4),mint=skin.optInt("mint",0xFFDDEDDC),cream=skin.optInt("cream",0xFFFFF5F0);\n  Bundle opts=manager.getAppWidgetOptions(id);int width=Math.max(220,Math.min(480,opts.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,280)));int height=Math.max(100,Math.min(220,opts.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,120)));Bitmap card=Bitmap.createBitmap(width*2,height*2,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(card);c.scale(2,2);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);p.setColor(cream);c.drawRoundRect(2,2,width-2,height-2,24,24,p);p.setStyle(Paint.Style.STROKE);p.setColor(pink);p.setStrokeWidth(2);c.drawRoundRect(2,2,width-2,height-2,24,24,p);p.setStyle(Paint.Style.FILL);\n  p.setColor(pink);for(int x=15;x<width;x+=31)for(int y=13;y<height;y+=31)c.drawCircle(x,y,1.6f,p);\n  float size=Math.min(92,height-20);Bitmap mascot=BitmapFactory.decodeFile(new File(context.getFilesDir(),"widget-character.png").toString());if(mascot!=null){c.drawBitmap(mascot,null,new RectF(10,(height-size)/2,10+size,(height+size)/2),p);mascot.recycle();}else{android.graphics.drawable.Drawable d=context.getDrawable(R.drawable.launcher_foreground);if(d!=null){d.setBounds(8,(int)((height-size)/2),(int)(8+size),(int)((height+size)/2));d.draw(c);}}\n  Typeface font=Typeface.create("sans-serif-rounded",Typeface.BOLD);try{font=Typeface.createFromAsset(context.getAssets(),"fonts/"+skin.optString("font","Mali")+".ttf");}catch(RuntimeException ignored){}p.setTypeface(font);p.setColor(ink);float x=size+20,available=width-x-15;p.setTextSize(17);while(p.measureText("A Day To Keep")>available&&p.getTextSize()>11)p.setTextSize(p.getTextSize()-1);float top=Math.max(26,height/2f-17);c.drawText("A Day To Keep",x,top,p);p.setTextSize(13);String status=total==0?"No tasks scheduled today":completed+" of "+total+" done today";while(p.measureText(status)>available&&p.getTextSize()>9)p.setTextSize(p.getTextSize()-1);c.drawText(status,x,top+23,p);\n  float barY=top+36;p.setColor(pink);c.drawRoundRect(x,barY,width-17,barY+11,5.5f,5.5f,p);if(total>0&&completed>0){p.setColor(mint);c.drawRoundRect(x,barY,x+available*((float)completed/total),barY+11,5.5f,5.5f,p);}RemoteViews views=new RemoteViews(context.getPackageName(),R.layout.keep_widget);views.setImageViewBitmap(R.id.widget_card,card);views.setContentDescription(R.id.widget_card,"A Day To Keep, "+status+", tap to open your checklist");Intent open=new Intent(context,MainActivity.class).putExtra("fromWidget",true).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent tap=PendingIntent.getActivity(context,701,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);views.setOnClickPendingIntent(R.id.widget_card,tap);manager.updateAppWidget(id,views);\n }catch(Exception|OutOfMemoryError e){android.util.Log.w("ADayToKeep","Could not render checklist widget",e);}}\n}\n'
