smoke='#!/usr/bin/env python3\nimport subprocess,time,re\nfrom pathlib import Path\nimport xml.etree.ElementTree as ET\nout=Path(\'startup-diagnostics\');out.mkdir(exist_ok=True)\npackage=\'uk.co.littledays\';recoveries=0\n\ndef adb(*args,check=True):\n result=subprocess.run([\'adb\',*args],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=100)\n if check and result.returncode:raise RuntimeError(result.stderr.decode(errors=\'replace\') or result.stdout.decode(errors=\'replace\'))\n return result.stdout.decode(errors=\'replace\')\n\ndef screenshot(name):\n with (out/(name+\'.png\')).open(\'wb\') as f:subprocess.run([\'adb\',\'exec-out\',\'screencap\',\'-p\'],stdout=f,check=True,timeout=45)\n\ndef texts(tree):return \' \'.join(n.get(\'text\',\'\')+\' \'+n.get(\'content-desc\',\'\') for n in tree.iter(\'node\'))\n\ndef alive():\n if not adb(\'shell\',\'pidof\',package,check=False).strip():raise RuntimeError(\'The app process exited\')\n report=adb(\'shell\',\'run-as\',package,\'cat\',\'files/last-crash.txt\',check=False)\n if report.strip():\n  (out/\'recorded-app-crash.txt\').write_text(report)\n  raise RuntimeError(\'The app recorded a crash; see recorded-app-crash.txt\')\n\ndef hierarchy(name):\n global recoveries\n for recovery in range(3):\n  last=None\n  for attempt in range(4):\n   try:\n    adb(\'shell\',\'uiautomator\',\'dump\',\'/sdcard/keep-ui.xml\')\n    xml=adb(\'exec-out\',\'cat\',\'/sdcard/keep-ui.xml\')\n    (out/(name+\'-\'+str(recovery)+\'.xml\')).write_text(xml)\n    tree=ET.fromstring(xml);break\n   except Exception as e:last=e;time.sleep(2)\n  else:raise RuntimeError(\'Cannot read UI hierarchy: \'+str(last))\n  try:screenshot(name+\'-\'+str(recovery))\n  except Exception as e:print(\'Screenshot unavailable:\',e)\n  text=texts(tree)\n  if "Pixel Launcher isn\'t responding" not in text and \'Pixel Launcher isn’t responding\' not in text:\n   if \'A_DAY_TO_KEEP_STARTUP_ERROR\' in text or \'startup report\' in text:raise RuntimeError(\'The app is displaying its startup-error report\')\n   if "isn\'t responding" in text or \'isn’t responding\' in text:raise RuntimeError(\'A non-launcher ANR was detected: \'+text)\n   return tree\n  if recoveries>=2:raise RuntimeError(\'The emulator Pixel Launcher repeatedly became unresponsive\')\n  close=next((n for n in tree.iter(\'node\') if n.get(\'resource-id\')==\'android:id/aerr_close\'),None)\n  if close is None:raise RuntimeError(\'Pixel Launcher ANR has no Close app control\')\n  bounds=[int(n) for n in re.findall(r\'\\d+\',close.get(\'bounds\',\'\'))]\n  if len(bounds)!=4:raise RuntimeError(\'Cannot locate launcher ANR control\')\n  recoveries+=1\n  (out/(\'launcher-recovery-\'+str(recoveries)+\'.txt\')).write_text(text)\n  adb(\'shell\',\'input\',\'tap\',str((bounds[0]+bounds[2])//2),str((bounds[1]+bounds[3])//2));time.sleep(3)\n  adb(\'shell\',\'am\',\'start\',\'-W\',\'-n\',package+\'/.MainActivity\');time.sleep(6);alive()\n raise RuntimeError(\'Could not recover launcher\')\n\ndef verify(tree,expected):\n if expected not in texts(tree):raise RuntimeError(\'Expected UI text missing: \'+expected)\n\ndef tap(tree,needle):\n for node in tree.iter(\'node\'):\n  if needle in node.get(\'content-desc\',\'\') or needle in node.get(\'text\',\'\'):\n   bounds=[int(n) for n in re.findall(r\'\\d+\',node.get(\'bounds\',\'\'))]\n   if len(bounds)==4 and bounds[2]>bounds[0] and bounds[3]>bounds[1]:\n    adb(\'shell\',\'input\',\'tap\',str((bounds[0]+bounds[2])//2),str((bounds[1]+bounds[3])//2));return\n raise RuntimeError(\'Cannot locate control: \'+needle)\n\ntry:\n apk=next(Path(\'android-project/app/build/outputs/apk/debug\').glob(\'*.apk\'))\n adb(\'install\',\'-r\',str(apk));adb(\'logcat\',\'-c\')\n adb(\'shell\',\'settings\',\'put\',\'secure\',\'show_ime_with_hard_keyboard\',\'1\',check=False)\n for iteration in range(2):\n  adb(\'shell\',\'am\',\'force-stop\',package)\n  result=adb(\'shell\',\'am\',\'start\',\'-W\',\'-n\',package+\'/.MainActivity\')\n  (out/(\'launch-\'+str(iteration)+\'.txt\')).write_text(result)\n  if \'Error:\' in result or \'Exception\' in result:raise RuntimeError(result)\n  time.sleep(8);alive();tree=hierarchy(\'home-\'+str(iteration));verify(tree,\'Work Schedule\');verify(tree,\'Daily Stuff\')\n tap(tree,\'Work Schedule\');time.sleep(2);tree=hierarchy(\'schedule\');verify(tree,\'Holiday\');verify(tree,\'Clear\')\n tap(tree,\'Next month\');time.sleep(1);tree=hierarchy(\'schedule-next\');tap(tree,\'Previous month\');time.sleep(1);tree=hierarchy(\'schedule-previous\');tap(tree,\'Done\');time.sleep(2)\n tree=hierarchy(\'home-return\');tap(tree,\'CPD\');time.sleep(3);alive();tree=hierarchy(\'cpd\');verify(tree,\'Add images\');verify(tree,\'Add PDF\');verify(tree,\'Previous\');verify(tree,\'Next\')\n tap(tree,\'CPD entry\');adb(\'shell\',\'input\',\'text\',\'CI_reflection_check\');time.sleep(4);tree=hierarchy(\'cpd-writing\');verify(tree,\'CPD entry\');verify(tree,\'Home\')\n # Confirm the IME appeared before asserting writing-mode controls are hidden.\n windows=adb(\'shell\',\'dumpsys\',\'input_method\',check=False)\n (out/\'keyboard-state.txt\').write_text(windows)\n if \'mInputShown=true\' in windows or \'isInputViewShown=true\' in windows:\n  if \'What happened? What did you learn?\' in texts(tree):raise RuntimeError(\'Journal prompt did not hide in writing mode\')\n adb(\'shell\',\'input\',\'keyevent\',\'4\');time.sleep(3);tree=hierarchy(\'cpd-restored\');verify(tree,\'Previous\');verify(tree,\'Today\');verify(tree,\'Add PDF\')\n tap(tree,\'Home\');time.sleep(2);tree=hierarchy(\'home-after-writing\');tap(tree,\'Settings\');time.sleep(3);tree=hierarchy(\'settings\');verify(tree,\'Settings\')\n tap(tree,\'Strawberry Bunny\');time.sleep(3);tree=hierarchy(\'theme-to-home\');verify(tree,\'Work Schedule\');verify(tree,\'Daily Stuff\')\n info=adb(\'shell\',\'dumpsys\',\'package\',package)\n (out/\'package-widget-registration.txt\').write_text(info)\n if \'KeepWidget\' not in info:raise RuntimeError(\'Widget receiver missing from installed package\')\n alive()\n print(\'PASS: repeat startup, schedule/month navigation, journal attachments, keyboard entry/return, theme-to-home and widget receiver registration. Launcher widget placement and visual motion still need device testing.\')\nfinally:\n for name,args in [(\'logcat.txt\',(\'logcat\',\'-d\',\'-v\',\'threadtime\')),(\'crash-buffer.txt\',(\'logcat\',\'-d\',\'-b\',\'crash\')),(\'activity-state.txt\',(\'shell\',\'dumpsys\',\'activity\',\'activities\'))]:\n  try:(out/name).write_text(adb(*args,check=False))\n  except Exception:pass\n try:(out/\'last-crash.txt\').write_text(adb(\'shell\',\'run-as\',package,\'cat\',\'files/last-crash.txt\',check=False))\n except Exception:pass\n'
